contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single public test function taking inputs used to call initialize and optionally send ETH
    function run(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) public payable {
        // Precondition: feeRate must be <= 5000 per contract requirement to avoid FeeRateTooHigh revert.
        // We don't require other conditions; if feeRate > 5000 the call should revert and we assert accordingly.
        bool reverted;
        // read before-values (views)
        bool beforeInitialized = c.initialized(); if (__ESBMC_reverted()) return;

        // perform the state-changing call at top level
        c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Observe public getters after the call
        bool afterInitialized = c.initialized(); if (__ESBMC_reverted()) return;
        address gotBaseToken = c.baseToken(); if (__ESBMC_reverted()) return;
        address gotNft = c.nft(); if (__ESBMC_reverted()) return;
        uint128 gotVirtualBase = c.virtualBaseTokenReserves(); if (__ESBMC_reverted()) return;
        uint128 gotVirtualNft = c.virtualNftReserves(); if (__ESBMC_reverted()) return;
        uint56 gotChangeFee = c.changeFee(); if (__ESBMC_reverted()) return;
        uint16 gotFeeRate = c.feeRate(); if (__ESBMC_reverted()) return;
        bytes32 gotMerkle = c.merkleRoot(); if (__ESBMC_reverted()) return;
        bool gotUseStolen = c.useStolenNftOracle(); if (__ESBMC_reverted()) return;
        bool gotPayRoyalties = c.payRoyalties(); if (__ESBMC_reverted()) return;

        // General rule:
        // If initialize did not revert, then afterInitialized must be true and the public getters must equal the inputs.
        // If initialize reverted, then either beforeInitialized was true (AlreadyInitialized) or feeRate > 5000 (FeeRateTooHigh) or initialized remains unchanged.
        // We encode this as a single assert over observed values and the revert flag.
        assert(
            // success case: not reverted implies values match and initialized became true
            (!reverted && afterInitialized &&
                gotBaseToken == _baseToken &&
                gotNft == _nft &&
                gotVirtualBase == _virtualBaseTokenReserves &&
                gotVirtualNft == _virtualNftReserves &&
                gotChangeFee == _changeFee &&
                gotFeeRate == _feeRate &&
                gotMerkle == _merkleRoot &&
                gotUseStolen == _useStolenNftOracle &&
                gotPayRoyalties == _payRoyalties
            )
            ||
            // revert case: either it was already initialized before, or feeRate was too high ( > 5000 ),
            // and in revert case the 'initialized' state must be unchanged (i.e., after == before)
            (reverted && (beforeInitialized || (_feeRate > 5000)) && (afterInitialized == beforeInitialized))
        );
    }

    // receive to allow ETH forwarding if ever needed by called functions
    receive() external payable {}
}

